def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# We want to test sizes |S| from 15 to 30.
# We use the constructive approach S = {0} U {F_2, F_3, ..., F_{m+1}}.
# The size of S is m+2. The maximum covered index K is m+1.
# For |S|=17, m=15, K=16.
# For |S|=30, m=28, K=29.

# Let's choose |S| = 27, which corresponds to m=25.
# This means S = {0, F_2, ..., F_26}.
set_size = 27
m = set_size - 2
if m < 0:
    print("Invalid set size.")
else:
    S = {0}
    for i in range(2, m + 2):
        S.add(fibonacci(i))

    # Calculate the coverage K. Since S explicitly contains F_2, ..., F_{m+1},
    # the coverage K is at least m+1.
    # K = m + 1 = 26.

    # For completeness, let's check the actual covered set of differences D(S)
    covered_fibs = set()
    fib_list = {}

    # Generate Fibonacci numbers up to F_{m+2} to check differences
    for i in range(2, m + 3):
        fib_list[i] = fibonacci(i)

    S_list = sorted(list(S))

    # Calculate all differences
    differences = set()
    for i in range(len(S_list)):
        for j in range(len(S_list)):
            if i != j:
                diff = S_list[i] - S_list[j]
                if diff > 0 and diff in fib_list.values():
                    # Check if the difference is a Fibonacci number
                    # We need to find the index k such that diff = F_k
                    found_k = None
                    for k, f_k in fib_list.items():
                        if f_k == diff:
                            found_k = k
                            break
                    if found_k is not None:
                         covered_fibs.add(found_k)

    # The coverage K is the maximum index found
    max_k_covered = max(covered_fibs) if covered_fibs else 0

    print(f"Test Set Size: {set_size}")
    print(f"Constructed Set S (size {len(S)}): {S_list[:5]} ... {S_list[-5:]}")
    print(f"Maximum covered index K: {max_k_covered}")

